function resultSummary(h){
 const person=callers.find(c=>c.id===h.caller);
 const actions=h.moves.map(id=>[...moves,...interactionMoves].find(m=>m.id===id)?.label).filter(Boolean);
 const reaction=[...(h.log||[])].reverse().find(line=>line.speaker===person.name)?.text;
 const outcome=h.outcome==='blocked'?'Tentativa interrompida':h.outcome==='fooled'?'Proposta aceita':'Conversa encerrada';
 const impact=resultImpact(h);
 return `<details class="result-summary"><summary class="result-card-toggle"><div class="result-heading"><strong>${escape(person.name)}</strong><span class="result-outcome ${h.outcome}">${outcome}</span></div><p class="result-context">${escape(impact?.summary||person.context)}</p></summary><div class="result-body"><p><b>Suas jogadas:</b> ${actions.length?actions.map(escape).join(' · '):h.audit?.length?'Conversa por mensagens digitadas; veja o replay abaixo.':'Nenhuma jogada registrada.'}</p>${reaction?`<blockquote><small>${escape(person.name)} respondeu</small><p>“${escape(reaction)}”</p></blockquote>`:''}<div class="result-explanation"><p>${escape(schemes.find(s=>s.id===h.scheme)?.name||person.context)}</p>${consequenceCard(h,escape)}${learningReplay(h)}${h.learningDefense?.result?`<div class="defense-history"><b>Defesa: ${escape(h.learningDefense.result.title)}</b><p>${escape(h.learningDefense.result.feedback)}</p></div>`:''}${h.defenseRound?`<div class="defense-history"><b>Na rodada de defesa:</b> ${escape(h.defenseRound.label)}<p>${escape(h.defenseRound.feedback)}</p></div>`:''}${h.steps?.length?`<p><b>Etapas:</b> ${h.steps.map(escape).join(' · ')}</p>`:''}${h.item?`<p><b>Item compartilhado:</b> ${escape(h.item.name)}</p>`:''}${h.scheme?`<p><b>Proposta:</b> ${escape(schemes.find(s=>s.id===h.scheme)?.name||'Proposta anterior')} · <b>Recebido:</b> C$ ${h.earned||0}</p>`:''}</div></div></details>`;
}
