 state.active.log.push({speaker:'Você',text:scheme.opening+(selectedOffer(state.active)?' Proposta: '+selectedOffer(state.active).name+'. '+selectedOffer(state.active).detail:'')},{speaker:caller.name,text:scheme.response});
