const windowViews=new Map();
try{const saved=JSON.parse(localStorage.getItem('qh-window-views')||'{}');for(const [id,view]of Object.entries(saved))if(appIds.includes(id)&&view?.positions&&Array.isArray(view.details))windowViews.set(id,view);}catch{}
const saveViews=()=>localStorage.setItem('qh-window-views',JSON.stringify(Object.fromEntries(windowViews)));
const scrollAreas=['.app-window-body','.call-window-body','.conversation','.choices','.debrief'];
function captureWindowViews(){
 for(const el of document.querySelectorAll('[data-window-id]')){
  const positions={};for(const selector of scrollAreas){const area=el.querySelector(selector);if(area)positions[selector]={top:area.scrollTop,bottom:area.scrollHeight-area.clientHeight-area.scrollTop<32,count:area.querySelectorAll('.bubble:not(.typing-bubble)').length,unread:windowViews.get(el.dataset.windowId)?.positions?.[selector]?.unread||0};}
  const details=[...el.querySelectorAll('details')].map(d=>({key:d.querySelector('summary')?.textContent,open:d.open}));
  windowViews.set(el.dataset.windowId,{positions,details});
 }
 saveViews();return windowViews;
}
function restoreWindowViews(views){
 for(const el of document.querySelectorAll('[data-window-id]')){
  const view=views.get(el.dataset.windowId);
  for(const d of el.querySelectorAll('details')){const old=view?.details.find(item=>item.key===d.querySelector('summary')?.textContent);if(old)d.open=old.open;}
  for(const selector of scrollAreas){const area=el.querySelector(selector),old=view?.positions[selector];if(!area)continue;
   if(selector==='.conversation'){const count=area.querySelectorAll('.bubble:not(.typing-bubble)').length,reading=readingPosition(old,count);area.scrollTop=reading.follow?area.scrollHeight:old.top;if(view?.positions)view.positions[selector]={...old,count,unread:reading.unread};if(reading.unread){const b=document.createElement('button');b.dataset.newMessages='true';b.className='new-message-jump';b.textContent=reading.unread+(reading.unread===1?' mensagem nova':' mensagens novas')+' · ir ao fim';area.after(b);}}else if(old)area.scrollTop=old.top;
  }
 }
}
let windows={calls:{x:170,y:65,z:2,hidden:false,max:false}};
