layer=Math.max(layer,...Object.values(windows).map(w=>w.z||0));opened=Object.entries(windows).filter(([,w])=>!w.hidden).sort((a,b)=>(b[1].z||0)-(a[1].z||0))[0]?.[0]||'calls';
