function render(){const previousViews=captureWindowViews();const focusElement=document.activeElement,focusButton=focusElement?.matches('button')?focusElement:null,focusAttribute=focusButton?[...focusButton.attributes].find(a=>a.name.startsWith('data-')):null;const focusId=document.activeElement?.id,focused=['player-message','caller-note','demo-card-number','chat-search'].includes(focusId),selection=focused?[document.activeElement.selectionStart,document.activeElement.selectionEnd]:null;saveWindows();const active=opened;let shell;const fragments=[];for(const [id,w]of Object.entries(windows)){if(w.hidden||(isMobile()&&id!==Object.entries(windows).filter(([,v])=>!v.hidden).sort((a,b)=>(b[1].z||0)-(a[1].z||0))[0]?.[0]))continue;opened=id;minimized=false;renderSingle();const el=document.querySelector('.desktop-window');el.dataset.windowId=id;if(id==='calls'&&!state.active&&!state.finished)el.classList.add('welcome-window');el.style.cssText=`left:${w.x}px;top:${w.y}px;z-index:${w.z||1}`;{if(w.width){el.style.width=Math.min(w.width,innerWidth-16)+'px';el.style.setProperty('--window-width',el.style.width);}if(w.height){el.style.height=Math.min(w.height,innerHeight-95)+'px';el.style.setProperty('--window-height',el.style.height);el.style.setProperty('--chat-height',Math.max(140,w.height-350)+'px');}el.insertAdjacentHTML('beforeend',`<button class="window-resize-side" data-resize-window="${id}" data-resize-axis="x" aria-label="Arraste a borda direita para ajustar a largura" title="Ajustar largura · setas do teclado" tabindex="0"></button><button class="window-resize-bottom" data-resize-window="${id}" data-resize-axis="y" aria-label="Arraste a borda inferior para ajustar a altura" title="Ajustar altura · setas do teclado" tabindex="0"></button><button class="window-resize-handle" data-resize-window="${id}" aria-label="Arraste o canto para ajustar largura e altura" title="Ajustar tamanho · setas do teclado" tabindex="0"></button>`);}if(w.max&&!isMobile())el.classList.add('maximized');else if(!isMobile()){const measured=el.getBoundingClientRect(),fit=fitWindow({x:w.x,y:w.y,width:measured.width,height:measured.height},{width:innerWidth,height:innerHeight});w.x=fit.x;w.y=fit.y;el.style.left=w.x+'px';el.style.top=w.y+'px';el.style.setProperty('--window-left',el.style.left);el.style.setProperty('--window-top',el.style.top);el.style.setProperty('--window-room',Math.max(1,innerHeight-57-w.y)+'px');if(w.width){el.style.width=(w.width=fit.width)+'px';el.style.setProperty('--window-width',el.style.width);}if(w.height){el.style.height=(w.height=fit.height)+'px';el.style.setProperty('--window-height',el.style.height);}}const bar=el.querySelector('.windowbar');bar.dataset.drag=id;bar.querySelector('div').insertAdjacentHTML('afterbegin',`<button data-max="${id}" aria-label="Maximizar ou restaurar janela">□</button>`);fragments.push(el.outerHTML);shell=document.querySelector('.desktop').outerHTML;}opened=active;if(!shell){minimized=true;renderSingle();shell=document.querySelector('.desktop').outerHTML;}app.innerHTML=shell;document.querySelector('.desktop-window')?.remove();document.querySelector('.desktop').insertAdjacentHTML('beforeend',fragments.join(''));document.querySelector('.start-menu').removeAttribute('data-app');document.querySelector('.start-menu').dataset.start='true';document.querySelector('.taskbar>small').textContent=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});if(startOpen)document.querySelector('.desktop').insertAdjacentHTML('beforeend',`<div class="os-start"><strong>TRAMBIQUE OS</strong><p>Estagiário · sessão local</p>${applications.map(([id,icon,name])=>`<button data-app="${id}">${icon} ${name}</button>`).join('')}<small>Trambique OS · todos os serviços são fictícios</small></div>`);restoreWindowViews(previousViews);saveWindows();document.querySelectorAll('[data-icon]').forEach((el,i)=>{const pos=iconPositions[el.dataset.icon]||{x:18,y:65+i*102};el.style.left=pos.x+'px';el.style.top=pos.y+'px';});if(focused){const input=document.getElementById(focusId);if(input){input.focus({preventScroll:true});input.setSelectionRange(...selection);}}if(!focused&&focusAttribute){const name=focusAttribute.name,value=focusAttribute.value;[...document.querySelectorAll('button')].find(b=>b.getAttribute(name)===value&&!b.disabled)?.focus({preventScroll:true});}const current=Object.entries(windows).filter(([,w])=>!w.hidden).sort((a,b)=>(b[1].z||0)-(a[1].z||0))[0]?.[0]||'calls';document.querySelector('.desktop').insertAdjacentHTML('beforeend',mobileNavigation(applications,current,{expanded:mobileAppsOpen,pending:!!state.incoming?.pending,unread:windowViews.get('calls')?.positions?.['.conversation']?.unread||0},desktopIcon));incomingMessages();applyConversationSearch();updatePortraits();const guide=tutorialPanel(state,escape,isMobile());document.querySelector(isMobile()?'.desktop-window>.call-window-body,.desktop-window>.app-window-body':'.desktop')?.insertAdjacentHTML(isMobile()?'afterbegin':'beforeend',guide);}
app.addEventListener('click',e=>{const b=e.target.closest('button'),win=e.target.closest('[data-window-id]');if(b?.hasAttribute('data-show-desktop')){const visible=Object.entries(windows).filter(([,w])=>!w.hidden);if(visible.length){desktopRestore=visible.map(([id])=>id);visible.forEach(([,w])=>w.hidden=true);}else if(desktopRestore){desktopRestore.forEach(id=>{if(windows[id])windows[id].hidden=false;});desktopRestore=null;}startOpen=false;render();return;}if(win)opened=win.dataset.windowId;if(b?.dataset.max){windows[b.dataset.max].max=!windows[b.dataset.max].max;render();}if(b?.dataset.start){startOpen=!startOpen;render();}if(b?.dataset.app){startOpen=false;mobileAppsOpen=false;}},true);
app.addEventListener('pointerdown',e=>{const win=e.target.closest('[data-window-id]');if(win){const w=windows[win.dataset.windowId];if(w){w.z=++layer;win.style.zIndex=w.z;}}const bar=e.target.closest('[data-drag]');if(!bar||e.target.closest('button')||isMobile())return;const id=bar.dataset.drag,w=windows[id];if(w.max)return;const sx=e.clientX,sy=e.clientY,x=w.x,y=w.y,el=bar.closest('[data-window-id]');w.z=++layer;el.style.zIndex=w.z;bar.setPointerCapture(e.pointerId);const move=ev=>{const r=el.getBoundingClientRect(),fit=fitWindow({x:x+ev.clientX-sx,y:y+ev.clientY-sy,width:r.width,height:r.height},{width:innerWidth,height:innerHeight});w.x=fit.x;w.y=fit.y;el.style.left=w.x+'px';el.style.top=w.y+'px';el.style.setProperty('--window-left',el.style.left);el.style.setProperty('--window-top',el.style.top);};const end=()=>{bar.removeEventListener('pointermove',move);bar.removeEventListener('pointerup',end);bar.removeEventListener('pointercancel',end);saveWindows();};bar.addEventListener('pointermove',move);bar.addEventListener('pointerup',end);bar.addEventListener('pointercancel',end);});
